/* Connected workspace views. All records remain studio data for this session. */
let routeParts = [], projectMode = 'board', crmMode = 'pipeline', agendaMode = 'week';
let ticketScope = 'All tickets', financeTab = 'overview', companyTab = 'team', selectedDay = CAL.focus;
/* On a new day the old selection may not be in the new week's grid, so the
   agenda re-opens on the new focus day. Once data is loaded, store.js owns the
   repaint (it trims and reloads the week's events on the same signal); before
   that there is nothing to wait for. Either way the repaint waits for any
   half-written draft — see repaintWhenIdle in app.js. */
CAL.onChange(()=>{selectedDay=CAL.focus;if(!(window.workspaceStore&&workspaceStore.state.loaded))repaintWhenIdle();});
const queries = {tickets:'', projects:'', crm:'', mail:''};


const originalOverview = overview, originalAction = action;
const money = v => Number(String(v).replace(/[^0-9.-]/g,''));
const usd = v => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
/* This month's income. Prefers workspace_overview(), which sums it in the
   database over every transaction — the browser only ever holds the last 180
   days, and a figure computed from a window is not the same figure. Falls back
   to the invoice list when the RPC is unavailable (a non-manager never sees
   either, and RLS makes both come back empty rather than wrong). */
const revenueThisMonth = () => {
  const o = window.workspaceStore && workspaceStore.state.overview;
  if (o && o.revenue_month !== null && o.revenue_month !== undefined) return Number(o.revenue_month);
  return invoices.filter(i => i.status === 'Paid').reduce((n, i) => n + money(i.amount), 0);
};
const matches = (q,...values) => values.join(' ').toLowerCase().includes(q.toLowerCase().trim());
const link = (route,label,ic='arrow',cls='text-btn') => `<a href="#${route}" class="${cls}">${ic?icon(ic):''}<span>${esc(label)}</span></a>`;
const empty = (title,body) => `<div class="workspace-empty">${icon('search')}<h3>${esc(title)}</h3><p>${esc(body)}</p></div>`;
const countTag = n => `<span class="small-count">${n}</span>`;
const titlebar = (title,subtitle,button='') => `<div class="page-heading app-heading"><div><div class="app-eyebrow">${icon(page)}<span>VEYAGO ${esc(navs.find(n=>n[0]===page)?.[1]||'WORKSPACE').toUpperCase()}</span></div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${button?`<div class="heading-actions">${button}</div>`:''}</div>`;
const createButton = (label,kind) => `<button class="btn btn-primary" data-create="${kind}">${icon('plus')}${label}</button>`;
const statStrip = items => `<div class="stat-strip">${items.map(([label,value,hint])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong>${hint?`<small>${esc(hint)}</small>`:''}</div>`).join('')}</div>`;
function queryInput(key,placeholder){return `<div class="list-search">${icon('search')}<input type="search" data-query="${key}" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(queries[key])}"></div>`;}
function segments(items,current,key){return `<div class="tabs" aria-label="View options">${items.map(([value,label])=>`<button data-view="${key}" data-value="${value}" class="${current===value?'active':''}" aria-pressed="${current===value}">${label}</button>`).join('')}</div>`;}
function detailHeader(parent,label,title,subtitle,actions=''){return `<div class="detail-back">${link(parent,label,'chevron')}</div>${titlebar(title,subtitle,actions)}`;}
function subnav(items,current){return `<nav class="subnav" aria-label="Page sections">${items.map(([path,label,key])=>`<a href="#${path}" class="${current===key?'selected':''}" ${current===key?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav>`;}
function properties(rows){return `<section class="panel property-panel"><h2>Details</h2>${rows.map(([k,v])=>`<div class="property-row"><span>${k}</span><div>${v}</div></div>`).join('')}</section>`;}
function selectField(label,kind,id,field,values,current){return `<select aria-label="${label}" data-record-kind="${kind}" data-record-id="${id}" data-field="${field}">${values.map(v=>`<option ${current===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`;}
function noteFeed(kind,id){let notes=recordNotes[kind][id]||[];return notes.length?notes.map(n=>`<article class="conversation-entry"><div class="avatar owner">${esc(n.initial||'V')}</div><div><div class="message-meta"><strong>${esc(n.who||'Veyago')}</strong><span>${esc(n.label||'Internal note')} · ${esc(n.time)}</span></div><p>${esc(n.body)}</p></div></article>`).join(''):'<p class="quiet-text">No notes yet. Add context for your next step.</p>';}
function noteForm(kind,id,label='Add a note'){return `<form class="note-form" data-note-form="${kind}" data-record-id="${id}"><label for="record-note">${label}</label><textarea id="record-note" name="note" required placeholder="Add an update, decision, or next step…"></textarea><div class="form-bottom"><span>Saved to the record</span><button class="btn btn-primary" type="submit">Save note</button></div></form>`;}
function notesPanel(kind,id){return `<section class="panel content-panel"><h2>Notes & updates</h2><div class="conversation-feed">${noteFeed(kind,id)}</div>${noteForm(kind,id)}</section>`;}
function activityRecord(message){workspaceActivity.unshift({message,time:'Just now'});}
function linkedPanel(title,items){return `<section class="panel content-panel related-panel"><h2>${title}</h2>${items.length?items.map(([route,label,meta,ic])=>`<a href="#${route}" class="related-item"><span class="related-icon">${icon(ic)}</span><div><strong>${esc(label)}</strong><small>${esc(meta)}</small></div>${icon('chevron')}</a>`).join(''):'<p class="quiet-text">No linked records yet.</p>'}</section>`;}
function notFound(){return `${detailHeader(page,'Back to '+page,'This record is unavailable.','Open another record from the app.')}<section class="panel">${empty('Record not found','It may have been removed, or this link is out of date.')}</section>`;}
function checkedTasks(p){return p.checked?.length||0;}
/* Who owns a project: the team member with its owner_id, not whoever is signed in. */
function projectOwner(p){return projectsModel.ownerOf(p,team);}
function ownerAvatar(p){const o=projectOwner(p);return `<span class="avatar sm owner" role="img" aria-label="${esc(o?'Owner: '+o.name:'No owner yet')}" title="${esc(o?o.name:'No owner yet')}">${esc(o?o.initial:'–')}</span>`;}
function ownerChip(p){const o=projectOwner(p);return o?`<span class="person-chip"><span class="avatar sm owner">${esc(o.initial)}</span>${esc(o.name)}</span>`:'<span class="quiet-text">No owner yet</span>';}
function taskRows(p,limit){const rows=p.tasks.map((t,i)=>({t,i}));return rows.slice(0,limit??rows.length).map(({t,i})=>`<label class="workspace-task"><input type="checkbox" data-project-task="${p.id}" data-task="${i}" data-task-id="${esc((p.taskIds||[])[i]||'')}" ${p.checked?.includes(i)?'checked':''}><span>${esc(t)}</span>${p.taskDue&&p.taskDue[i]?`<small> ${esc(p.taskDue[i])}</small>`:''}</label>`).join('');}

/* Overview: actionable personal focus and cross-app work. */
overview = function(){let base=originalOverview();/* the activity list is rendered in app.js now, from the same array *//* Guarded: with no projects yet, projects[0] is undefined and this used to
   throw before the Overview could paint its empty state. */
if(projects[0]&&projects[0].tasks.length){const p0=projects[0],done=checkedTasks(p0);
  base=base.replace('<strong>72%</strong>','<strong>'+done+' / '+p0.tasks.length+' tasks</strong>')
           .replace('<div class="progress"><i style="width:72%"></i></div>','<div class="progress"><i style="width:'+Math.round(done/p0.tasks.length*100)+'%"></i></div>');}const focus=projects.flatMap(p=>p.tasks.map((t,i)=>({p,t,i}))).filter(({p,i})=>!p.checked?.includes(i)).slice(0,3);const block=`<section class="panel focus-panel"><div class="focus-intro"><span class="eyebrow">MY FOCUS</span><h2>Move your day forward.</h2><p>${openTickets().length} open tickets · ${projects.filter(projectsModel.isActive).length} active projects</p></div><div class="focus-items">${focus.map(({p,t,i})=>`<div class="focus-item"><label><input type="checkbox" data-project-task="${p.id}" data-task="${i}" data-task-id="${esc((p.taskIds||[])[i]||'')}"><span>${esc(t)}</span></label>${link('projects/'+p.id+'/tasks',p.name,'chevron')}</div>`).join('')||'<p class="quiet-text">Your project tasks are complete.</p>'}</div></section>`;return base.replace('<div class="metrics">',block+'<div class="metrics">');};

/* Ticket queues and the ticket workspace. */
ticketsView = function(){if(routeParts[1])return ticketDetail(Number(routeParts[1]));const list=tickets.filter(t=>(ticketScope==='All tickets'||ticketScope==='Assigned to me'&&t.owner==='C'||ticketScope==='High priority'&&t.priority==='High'||t.status===ticketScope)&&matches(queries.tickets,t.title,t.client,t.product,t.id));return titlebar('Support, with context.','Keep every customer conversation moving.',createButton('New ticket','tickets'))+statStrip([['Open',openTickets().length,'Across all products'],['Assigned to you',openTickets().filter(t=>t.owner===(window.workspaceData&&window.workspaceSession&&workspaceSession.employee?workspaceData.initials(workspaceSession.employee.full_name):'C')).length,(window.workspaceSession&&workspaceSession.employee?workspaceSession.employee.full_name:'You')],['High priority',openTickets().filter(t=>t.priority==='High').length,'Needs attention'],['Resolved',tickets.filter(t=>t.status==='Resolved').length,'This session']])+`<div class="queue-layout"><aside class="panel queue-sidebar"><span class="eyebrow">VIEWS</span>${['All tickets','Assigned to me','High priority','Open','In progress','Resolved'].map(f=>`<button data-view="ticketScope" data-value="${f}" class="${ticketScope===f?'selected':''}">${icon(f==='Assigned to me'?'crm':'tickets')}<span>${f}</span></button>`).join('')}<div class="queue-hint">${icon('tickets')}<p>Replies and internal notes stay with each ticket.</p></div></aside><section class="panel"><div class="list-toolbar"><h2>${esc(ticketScope)} ${countTag(list.length)}</h2>${queryInput('tickets','Search tickets')}</div>${list.length?ticketTable(list,true):empty('No tickets here','Try another view or a different search.')}<div class="table-bottom"><span>${list.length} ticket${list.length===1?'':'s'}</span><span>Replies are written to the ticket</span></div></section></div>`;};
function ticketDetail(id){const t=tickets.find(t=>t.id===id);if(!t)return notFound();const contact=contacts.findIndex(c=>c.name===t.client);const project=projects.find(p=>p.client===t.product||p.name.startsWith(t.product));return detailHeader('tickets','All tickets',t.title,`VYG-${t.id} · ${t.client}`,`<button class="btn ${t.status==='Resolved'?'':'btn-primary'}" data-action="resolve" data-id="${t.id}">${icon('check')}${t.status==='Resolved'?'Reopen ticket':'Resolve ticket'}</button>`)+`<div class="record-layout"><div class="record-main"><section class="panel content-panel"><div class="section-title"><h2>Conversation</h2>${pill(t.product,'blue')}</div><div class="conversation-feed"><article class="conversation-entry"><div class="avatar">${esc(t.client.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><div class="message-meta"><strong>${esc(t.client)}</strong><span>${esc(t.date)} · Customer</span></div><p>${esc(t.body)}</p></div></article>${(recordNotes.tickets[id]||[]).length?noteFeed('tickets',id):''}</div><form class="ticket-reply-form" data-ticket-reply="${id}"><div class="reply-controls"><label><input type="radio" name="mode" value="Demo reply" checked> Reply</label><label><input type="radio" name="mode" value="Internal note"> Internal note</label></div><label class="sr-only" for="ticket-response">Message</label><textarea id="ticket-response" name="body" required placeholder="Write a reply or leave a note for the team…"></textarea><div class="form-bottom"><span>Demo only · No external email sent</span><button class="btn btn-primary">Add message ${icon('arrow')}</button></div></form></section></div><aside class="record-aside">${properties([['Status',selectField('Ticket status','tickets',id,'status',['Open','In progress','Resolved'],t.status)],['Priority',selectField('Ticket priority','tickets',id,'priority',['Low','Medium','High'],t.priority)],['Owner',(()=>{let f=selectField('Ticket owner','tickets',id,'owner',team.map(m=>m.initial),t.owner);team.forEach(m=>{f=f.replace('>'+m.initial+'</option>','>'+esc(m.name)+'</option>');});return f;})()],['Product',esc(t.product)],['Requester',esc(t.client)]])}${linkedPanel('Connected work',[...(contact>=0?[[`crm/${contact}`,t.client,'Contact profile','crm']]:[]),...(project?[[`projects/${project.id}`,project.name,'Project workspace','projects']]:[])])}</aside></div>`;}

/* Mail: mailboxes, folders, conversations and the reading pane live in mail.js. */

/* Projects: board, list and full task workspaces. */
projectsView = function(){if(routeParts[1]!==undefined)return projectDetail(String(routeParts[1]));const list=projects.filter(p=>matches(queries.projects,p.name,p.client));return titlebar('Make room for good work.','Products, client work, and everything moving toward launch.',createButton('New project','projects'))+statStrip([['Active projects',projects.filter(projectsModel.isActive).length,'Across the studio'],['In review',projects.filter(p=>p.status==='In review').length,'Ready for a closer look'],['Open tasks',projects.reduce((a,p)=>a+p.tasks.length-checkedTasks(p),0),'Across all projects'],['Completed tasks',projects.reduce((a,p)=>a+checkedTasks(p),0),'Done so far']])+`<div class="view-toolbar">${segments([['board','Board'],['list','List']],projectMode,'projectMode')}${queryInput('projects','Search projects')}</div>${projectMode==='board'?`<div class="project-board stage-board">${projectsModel.boardColumns(list).map(({status,projects:items})=>`<section class="board-column"><div class="board-heading"><h2>${status}</h2>${countTag(items.length)}</div><div class="board-cards">${items.map(p=>projectTile(p)).join('')||'<div class="board-empty">No projects in this stage.</div>'}</div></section>`).join('')}</div>`:`<section class="panel"><div class="table-wrap"><table class="module-table"><thead><tr><th>Project</th><th>Status</th><th>Tasks</th><th>Due</th></tr></thead><tbody>${list.map(p=>`<tr data-action="project" data-id="${p.id}" role="button" tabindex="0"><td><div class="cell-main"><div class="project-logo ${p.style}">${esc(p.initial)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.client)}</small></div></div></td><td>${pill(p.status)}</td><td>${checkedTasks(p)} / ${p.tasks.length}</td><td>${esc(p.due)}</td></tr>`).join('')}</tbody></table>${!list.length?empty('No projects found','Try another search.'):''}</div></section>`}`;};
function projectTile(p){return `<a class="project-card board-card" href="#projects/${p.id}"><div class="card-top"><div class="project-logo ${p.style}">${esc(p.initial)}</div><span class="card-arrow">${icon('chevron')}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="card-task-progress"><span>${checkedTasks(p)} of ${p.tasks.length} tasks complete</span><span>${p.tasks.length?Math.round(checkedTasks(p)/p.tasks.length*100):0}%</span></div><div class="progress"><i style="width:${p.tasks.length?checkedTasks(p)/p.tasks.length*100:0}%"></i></div><div class="project-card-bottom">${ownerAvatar(p)}${p.due?`<span>Due ${esc(p.due)}</span>`:''}</div></a>`;}
function projectDetail(id){const p=projects.find(p=>p.id===id);if(!p)return notFound();const tab=routeParts[2]||'overview';const byCompany=p.companyId?contacts.findIndex(c=>c.row&&c.row.company&&c.row.company.id===p.companyId):-1;const ci=byCompany>=0?byCompany:contacts.findIndex(c=>c.company===p.client);const related=projectsModel.projectTickets(tickets,p);const meetings=projectsModel.upcomingEvents((window.workspaceStore&&workspaceStore.state.projectEvents)||[],p,Date.now());const taskPanel=`<section class="panel content-panel"><div class="section-title"><h2>Tasks</h2><span class="quiet-text">${checkedTasks(p)} / ${p.tasks.length} complete</span></div><div class="task-list">${taskRows(p)}</div><form class="add-task-form" data-add-task="${p.id}"><input name="task" required aria-label="New task" placeholder="Add a task to this project…"><button class="btn" type="submit">${icon('plus')}Add task</button></form></section>`;return detailHeader('projects','All projects',p.name,p.client,pill(p.status)+(typeof projectsUi!=='undefined'?projectsUi.actions(p):''))+subnav([['projects/'+id,'Overview','overview'],['projects/'+id+'/tasks','Tasks','tasks'],['projects/'+id+'/notes','Notes','notes']],tab)+`<div class="record-layout"><div class="record-main">${tab==='notes'?notesPanel('projects',id):tab==='tasks'?taskPanel:`<section class="panel project-summary"><div class="project-logo ${p.style}">${esc(p.initial)}</div><div><span class="eyebrow">PROJECT BRIEF</span><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p></div><div class="project-completion"><strong>${checkedTasks(p)}<span> / ${p.tasks.length}</span></strong><small>tasks complete</small></div></section>${taskPanel}`}</div><aside class="record-aside">${properties([['Status',selectField('Project status','projects',id,'status',projectsModel.STATUS_LABELS,p.status)],['Owner',ownerChip(p)],['Due date',esc(p.due||'Not set')],['Client / product',esc(p.client)]])}${linkedPanel('Connected work',[...(ci>=0?[[`crm/${ci}`,contacts[ci].name,p.client,'crm']]:[]),...related.map(t=>[`tickets/${t.id}`,t.title,'VYG-'+t.id+' · '+t.status+(t.row&&t.row.project_id?'':' · not filed under a project'),'tickets'])])}${linkedPanel('Meetings',meetings.map(ev=>[events.some(e=>e.id===ev.id)?'agenda/'+ev.id:'agenda',ev.title,ev.when,'agenda']))}</aside></div>`;}

/* CRM: contacts and pipeline share complete relationship pages. */
crmView = function(){if(routeParts[1]!==undefined)return contactDetail(Number(routeParts[1]));const list=contacts.map((c,i)=>({c,i})).filter(({c})=>matches(queries.crm,c.name,c.company,c.email));return titlebar('Good relationships, in one place.','Keep the people, conversations, and work connected.',createButton('Add contact','crm'))+statStrip([['Contacts',contacts.length,'People in your network'],['Pipeline value',usd(contacts.filter(c=>c.stage!=='Client').reduce((a,c)=>a+money(c.value),0)),'Leads and proposals'],['Active clients',contacts.filter(c=>c.stage==='Client').length,'Ongoing relationships']])+`<div class="view-toolbar">${segments([['pipeline','Pipeline'],['contacts','Contacts']],crmMode,'crmMode')}${queryInput('crm','Search contacts')}</div>${crmMode==='pipeline'?`<div class="project-board crm-board">${['Lead','Proposal','Client'].map(stage=>`<section class="board-column"><div class="board-heading"><h2>${stage==='Client'?'Clients':stage==='Lead'?'Leads':'Proposals'}</h2>${countTag(list.filter(({c})=>c.stage===stage).length)}</div><div class="board-cards">${list.filter(({c})=>c.stage===stage).map(({c,i})=>`<a class="panel contact-card" href="#crm/${i}"><div class="card-top"><div class="avatar contact-avatar">${esc(c.initial)}</div>${icon('chevron')}</div><h2>${esc(c.company)}</h2><p>${esc(c.name)}</p><div class="contact-value"><strong>${esc(c.value)}</strong><span>Opportunity</span></div><small>${esc(c.email)}</small></a>`).join('')||'<div class="board-empty">No contacts in this stage.</div>'}</div></section>`).join('')}</div>`:`<section class="panel"><div class="table-wrap"><table class="module-table"><thead><tr><th>Contact</th><th>Company</th><th>Stage</th><th>Opportunity</th></tr></thead><tbody>${list.map(({c,i})=>`<tr data-action="contact" data-id="${i}" role="button" tabindex="0"><td><div class="cell-main"><div class="avatar">${esc(c.initial)}</div><div><strong>${esc(c.name)}</strong><small>${esc(c.email)}</small></div></div></td><td>${esc(c.company)}</td><td>${pill(c.stage)}</td><td>${esc(c.value)}</td></tr>`).join('')}</tbody></table>${!list.length?empty('No contacts found','Try searching a name or company.'):''}</div></section>`}`;};
function contactDetail(id){const c=contacts[id];if(!c)return notFound();const tab=routeParts[2]||'overview';const ps=projects.filter(p=>p.client===c.company),ts=tickets.filter(t=>t.client===c.name||t.product===c.company),ms=mails.map((m,i)=>({m,i})).filter(({m})=>m.email===c.email),ivs=invoices.map((i,n)=>({i,n})).filter(({i})=>i.client===c.company);return detailHeader('crm','All contacts',c.name,c.company,`<button class="btn btn-primary" data-action="contact-email" data-id="${id}">${icon('mail')}Write email</button>`)+subnav([[`crm/${id}`,'Overview','overview'],[`crm/${id}/activity`,'Activity & notes','activity']],tab)+`<div class="record-layout"><div class="record-main">${tab==='overview'?`<section class="panel contact-summary"><div class="avatar contact-avatar">${esc(c.initial)}</div><div><span class="eyebrow">${esc(c.company)}</span><h2>${esc(c.name)}</h2><p>${esc(c.email)}</p></div>${pill(c.stage)}</section><section class="panel content-panel"><h2>Relationship brief</h2><p class="body-copy">${esc(c.notes)}</p></section>${linkedPanel('Projects & support',[...ps.map(p=>[`projects/${p.id}`,p.name,'Project','projects']),...ts.map(t=>[`tickets/${t.id}`,t.title,'VYG-'+t.id,'tickets'])])}${linkedPanel('Conversations & invoices',[...ms.map(({m})=>[mailModel.mailRoute({mailbox:mailModel.ALL,folder:m.folder==='sent'?'sent':'inbox',threadId:m.id}),m.subject,m.time,'mail']),...ivs.map(({i,n})=>[`finance/${n}`,i.id+' · '+i.amount,i.status,'finance'])])}`:notesPanel('crm',id)}</div><aside class="record-aside">${properties([['Stage',selectField('Relationship stage','crm',id,'stage',['Lead','Proposal','Client'],c.stage)],['Opportunity',`<strong>${esc(c.value)}</strong>`],['Company',esc(c.company)],['Email',`<span class="break-word">${esc(c.email)}</span>`],['Owner','Cassian']])}<section class="panel content-panel"><h2>Relationship activity</h2><div class="relationship-counts"><span><strong>${ps.length}</strong>Projects</span><span><strong>${ts.length}</strong>Tickets</span><span><strong>${ms.length}</strong>Emails</span></div></section></aside></div>`;}

/* Calendar: week, day and agenda views with dedicated event pages. */
agendaView = function(){if(routeParts[1]!==undefined)return eventDetail(routeParts[1]);const todayEvents=events.filter(e=>e.day===selectedDay).sort((a,b)=>a.time.localeCompare(b.time));const eventCard=e=>`<a class="calendar-event type-${e.type.toLowerCase()}" href="#agenda/${esc(e.id)}"><small>${esc(e.time)} – ${esc(e.end)}</small><strong>${esc(e.title)}</strong><small>${esc(e.detail)}</small></a>`;return titlebar('A little space for what’s next.','Your meetings and focused work, together.',createButton('New event','agenda'))+`<div class="view-toolbar"><h2>${CAL.range()}</h2>${segments([['week','Week'],['day','Day'],['schedule','Schedule']],agendaMode,'agendaMode')}</div><div class="calendar-layout"><aside class="calendar-side"><section class="panel mini-calendar"><div class="section-title"><h2>${CAL.monthName}</h2><span>${CAL.year}</span></div><div class="mini-week">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="mini-days">${CAL.month().cells.map(c=>c.inWeek?`<button data-day="${c.day}" class="${c.day===selectedDay?'selected':''}" aria-label="${CAL.full(c.day)}" aria-pressed="${c.day===selectedDay}">${c.day}</button>`:`<span${c.inMonth?'':' class="outside"'}>${c.day}</span>`).join('')}</div><p class="quiet-text">${CAL.isNextWeek?'Next week':'This week'} · ${CAL.range(false)}</p></section><section class="panel content-panel"><h2>Calendars</h2><div class="calendar-key"><span class="key-blue"></span>Team</div><div class="calendar-key"><span class="key-purple"></span>Clients</div><div class="calendar-key"><span class="key-teal"></span>Products</div></section></aside><div class="calendar-primary">${agendaMode==='week'?`<section class="panel calendar">${CAL.short.map((d,i)=>`<div class="calendar-day ${CAL.dates[i]===selectedDay?'today':''}"><button class="calendar-day-button" data-day="${CAL.dates[i]}"><span>${d}</span><strong>${CAL.dates[i]}</strong></button>${events.filter(e=>e.day===CAL.dates[i]).sort((a,b)=>a.time.localeCompare(b.time)).map(eventCard).join('')||'<div class="empty-calendar">Room to focus</div>'}</div>`).join('')}</section>`:agendaMode==='day'?`<section class="panel day-view"><div class="list-toolbar"><h2>${CAL.nameFor(selectedDay)}, ${CAL.label(selectedDay)}</h2>${countTag(todayEvents.length)}</div>${todayEvents.length?todayEvents.map(e=>`<div class="day-event"><div class="day-event-time">${e.time}<small>${e.end}</small></div>${eventCard(e)}</div>`).join(''):empty('A clear day','Add an event or use the space to focus.')}</section>`:`<section class="panel schedule-view">${CAL.dates.map(d=>`<div class="schedule-date">${CAL.nameFor(d)}<strong>${CAL.label(d)}</strong></div>${events.filter(e=>e.day===d).sort((a,b)=>a.time.localeCompare(b.time)).map(e=>`<a href="#agenda/${esc(e.id)}" class="schedule-row"><span>${e.time} – ${e.end}</span><strong>${esc(e.title)}</strong>${pill(e.type,e.type==='Client'?'purple':e.type==='Product'?'green':'blue')}</a>`).join('')||'<p class="quiet-text schedule-empty">No events scheduled.</p>'}`).join('')}</section>`}</div></div>`;};
function eventDetail(id){const e=events.find(ev=>ev.id===id);if(!e)return notFound();const ci=contacts.findIndex(c=>e.detail.includes(c.name));const project=projects.find(p=>e.title.toLowerCase().includes(p.name.split(' ·')[0].toLowerCase()));return detailHeader('agenda','Calendar',e.title,(CAL.nameFor(e.day)||'')+`, ${CAL.full(e.day)}`)+`<div class="record-layout"><div class="record-main"><section class="panel event-summary"><div class="date-tile"><span>${CAL.monthAbbr(e.day)}</span><strong>${e.day}</strong></div><div><h2>${esc(e.title)}</h2><p>${esc(e.time)} – ${esc(e.end)}</p><small>${esc(e.detail)}</small></div>${pill(e.type,'blue')}</section>${e.notes?`<section class="panel content-panel"><h2>Meeting brief</h2><p class="body-copy">${esc(e.notes)}</p></section>`:''}${notesPanel('agenda',id)}</div><aside class="record-aside">${properties([['Date',CAL.full(e.day)],['Time',e.time+' – '+e.end],['Calendar',pill(e.type,'blue')],['Attendees',esc(e.detail.split(' · ')[0])],['Meeting',esc(e.detail.split(' · ')[1]||'Not specified')]])}${linkedPanel('Connected work',[...(ci>=0?[[`crm/${ci}`,contacts[ci].name,contacts[ci].company,'crm']]:[]),...(project?[[`projects/${project.id}`,project.name,'Project workspace','projects']]:[])])}<p class="aside-note">Event. Calendar and video meeting services are not connected.</p></aside></div>`;}

/* Finance: relevant finance metrics, invoice list and invoice documents. */
financeView = function(){if(routeParts[1]!==undefined&&/^\d+$/.test(routeParts[1]))return invoiceDetail(Number(routeParts[1]));financeTab=routeParts[1]==='invoices'?'invoices':'overview';const paid=invoices.filter(i=>i.status==='Paid').reduce((n,i)=>n+money(i.amount),0),due=invoices.filter(i=>i.status!=='Paid').reduce((n,i)=>n+money(i.amount),0);return titlebar('A clear view of the business.','Income, invoices, and the clients behind them.')+subnav([['finance','Overview','overview'],['finance/invoices','Invoices','invoices']],financeTab)+statStrip([['Revenue this month',usd(revenueThisMonth()),CAL.thisMonth+' · from transactions'],['Listed invoices',usd(paid+due),invoices.length+' invoices'],['Paid invoices',usd(paid),'From the invoice list'],['Awaiting payment',usd(due),'Due September 15']])+`${financeTab==='overview'?`<div class="financial-grid">${revenueChart()}<section class="panel breakdown"><div class="section-title"><h2>Revenue mix</h2><span class="quiet-text">${CAL.thisMonth}</span></div>${(()=>{const mix=(window.workspaceStore&&workspaceStore.state.revenueMix)||[];
if(!mix.length)return '<p class="quiet-text" style="padding:14px 0">No income recorded this month yet.</p>';
const total=mix.reduce((n,m)=>n+Number(m.amount),0);
return `<div class="revenue-mix-total">${usd(total)} <small>USD</small></div><div class="mix-bar">${mix.map(m=>`<i style="width:${Number(m.share)}%"></i>`).join('')}</div>${mix.map((m,i)=>`<div class="mix-row"><span><i class="mix-dot mix-${i%3}"></i>${esc(m.category)}</span><strong>${usd(Number(m.amount))}</strong><small>${Number(m.share)}%</small></div>`).join('')}<p class="quiet-text">Values in USD, from posted transactions.</p>`;})()}</section></div>`:''}<section class="panel"><div class="list-toolbar"><h2>${financeTab==='overview'?'Recent invoices':'Invoices'} ${countTag(invoices.length)}</h2><span class="quiet-text">USD · from the invoice ledger</span></div><div class="table-wrap"><table class="module-table"><thead><tr><th>Invoice</th><th>Client</th><th>Amount</th><th>Status</th><th>Due / paid</th><th></th></tr></thead><tbody>${invoices.map((i,n)=>`<tr data-action="invoice" data-id="${n}" role="button" tabindex="0" aria-label="Open invoice ${i.id}"><td><strong>${i.id}</strong></td><td><div class="cell-main"><div><strong>${esc(i.client)}</strong><small>${esc(i.description)}</small></div></div></td><td>${i.amount}</td><td>${pill(i.status)}</td><td>${i.date}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div></section>`;};
function invoiceDetail(id){const i=invoices[id];if(!i)return notFound();const c=contacts.findIndex(c=>c.company===i.client);return detailHeader('finance/invoices','All invoices',i.id,i.client,`<button class="btn" data-print-invoice>${icon('external')}Print invoice</button>`)+`<div class="record-layout invoice-layout"><section class="panel invoice-document"><div class="invoice-heading"><div><span class="invoice-wordmark">Veyago</span><p>Veyago Inc.<br>New York, United States<br>hello@veyago.cloud</p></div><div><h2>Invoice</h2><p>${i.id}</p>${pill(i.status)}</div></div><div class="invoice-parties"><div><span class="eyebrow">BILL TO</span><h3>${esc(i.client)}</h3>${c>=0?`<p>${esc(contacts[c].name)}<br>${esc(contacts[c].email)}</p>`:''}</div><div><span class="eyebrow">${i.status==='Paid'?'PAID ON':'DUE DATE'}</span><p>${i.date}</p><span class="quiet-text">Currency: USD</span></div></div><div class="table-wrap"><table class="invoice-lines"><thead><tr><th>Description</th><th>Qty</th><th>Amount</th></tr></thead><tbody><tr><td>${esc(i.description)}</td><td>1</td><td>${i.amount}</td></tr></tbody></table></div><div class="invoice-total"><span>Total</span><strong>${i.amount} <small>USD</small></strong></div><div class="invoice-note"><h3>Thank you for building with Veyago.</h3><p>Issued from the workspace. This is not a payment request or an accounting document.</p></div></section><aside class="record-aside">${properties([['Status',pill(i.status)],['Total',i.amount],['Balance due',i.status==='Paid'?'$0':i.amount],['Currency','USD']])}${linkedPanel('Client relationship',c>=0?[[`crm/${c}`,contacts[c].name,i.client,'crm']]:[])}<p class="aside-note">Payments and accounting services are not connected.</p></aside></div>`;}

/* Company: people, studio profile and workspace preferences. */
/* Empty for the same reason as the arrays in app.js: the store fills them. */

companyView = function(){if(routeParts[1]==='people')return personDetail(Number(routeParts[2]));companyTab=['studio','preferences'].includes(routeParts[1])?routeParts[1]:'team';return titlebar('The studio behind the work.','People, company details, and your workspace.')+subnav([['company','People','team'],['company/studio','Studio','studio'],['company/preferences','Preferences','preferences']],companyTab)+(companyTab==='team'?`<div class="people-grid">${team.map((p,i)=>`<a href="#company/people/${i}" class="panel person-card"><div class="person-cover"><div class="avatar ${i===0?'owner':''}">${esc(p.initial)}</div></div><div class="person-info"><div class="section-title"><h2>${esc(p.name)}</h2>${icon('chevron')}</div><p>${esc(p.role)}</p><span class="pill ${i===0?'blue':'purple'}">${esc(p.tag)}</span><div class="person-work-count"><span>${tickets.filter(t=>t.owner===(i===0?'C':'JD')&&t.status!=='Resolved').length} open tickets</span><span>${projects.filter(pr=>pr.ownerId===p.id).length} owned projects</span></div></div></a>`).join('')}<section class="panel team-context"><span class="eyebrow">VEYAGO INC.</span><h2>A shared place to work.</h2><p>The same conversations, project tasks, and client context—available across your workspace.</p>${link('company/studio','View studio details','arrow')}</section></div>`:companyTab==='studio'?`<div class="record-layout"><div class="record-main"><section class="panel content-panel studio-profile"><span class="brand-glyph">V</span><h2>Veyago Inc.</h2><p class="body-copy">Independent software studio. Software for the journey.</p><div class="studio-facts"><div><span>Location</span><strong>New York, United States</strong></div><div><span>Contact</span><strong>hello@veyago.cloud</strong></div></div><a class="btn" href="https://www.veyago.cloud/" target="_blank" rel="noopener">Company website ${icon('external')}</a></section>${linkedPanel('Products',projects.filter(p=>p.client==='Internal product').map(p=>[`projects/${p.id}`,p.name,p.status,'projects']))}</div><aside class="record-aside"><section class="panel content-panel"><h2>Workspace apps</h2>${navs.slice(1,7).map(([id,label])=>`<a class="studio-app" href="#${id}">${icon(id)}<span>${label}</span>${icon('chevron')}</a>`).join('')}</section></aside></div>`:`<section class="panel preferences-panel"><div class="preference-heading"><h2>Workspace appearance</h2><p>These preferences apply to this browser.</p></div><div class="preference-row"><div><h3>Compact spacing</h3><p>Fit more records into your working view.</p></div><label class="switch"><input id="compact-setting" type="checkbox" ${document.body.classList.contains('compact')?'checked':''} aria-label="Compact spacing"><span></span></label></div><div class="preference-row"><div><h3>Motion effects</h3><p>Animate subtle transitions between views.</p></div><label class="switch"><input id="motion-setting" type="checkbox" ${!document.body.classList.contains('no-motion')?'checked':''} aria-label="Motion effects"><span></span></label></div><div class="preference-heading"><h2>About this workspace</h2><p>Studio data · Session changes reset when you reload. Mail, calendar, accounting, and team services are not connected.</p></div><div class="shortcut-row"><span>Search workspace</span><kbd>/</kbd></div><div class="shortcut-row"><span>Close dialog or search</span><kbd>esc</kbd></div></section>`);};
function personDetail(id){const p=team[id];if(!p)return notFound();const owner=id===0?'C':'JD';return detailHeader('company','People',p.name,p.role)+`<div class="record-layout"><div class="record-main"><section class="panel contact-summary"><div class="avatar contact-avatar ${id===0?'owner':''}">${esc(p.initial)}</div><div><h2>${esc(p.name)}</h2><p>${esc(p.focus)}</p></div>${pill(p.tag,'blue')}</section>${linkedPanel('Assigned tickets',tickets.filter(t=>t.owner===owner).map(t=>[`tickets/${t.id}`,t.title,t.status,'tickets']))}${linkedPanel('Owned projects',projects.filter(pr=>pr.ownerId===p.id).map(pr=>[`projects/${pr.id}`,pr.name,pr.status,'projects']))}</div><aside class="record-aside">${properties([['Role',esc(p.role)],['Open tickets',tickets.filter(t=>t.owner===owner&&t.status!=='Resolved').length],['Workspace','Veyago Inc.']])}</aside></div>`;}

/* Routes and transitions. Existing create, compose and search workflows remain available. */
showTicket = id => {modal.close();navigate('tickets/'+id);};
showProject = id => {modal.close();navigate('projects/'+id);};
showContact = id => {modal.close();navigate('crm/'+id);};
showEvent = id => {modal.close();navigate('agenda/'+id);};
action = function(name,id){if(name==='invoice'){modal.close();navigate('finance/'+id);return;}originalAction(name,id);};
render = function(){nav();const label=navs.find(n=>n[0]===page)?.[1]||'Overview';document.querySelector('#breadcrumb').textContent=label+(routeParts[1]? ' / '+(page==='mail'?mailFolder:'Details'):'');document.querySelector('#main').innerHTML=({overview,tickets:ticketsView,mail:mailView,projects:projectsView,crm:crmView,agenda:agendaView,finance:financeView,company:companyView}[page])();document.title=label+' — Veyago Workspace';};
navigate = function(target){if(modal.open)modal.close();const parts=String(target||'overview').split('/');if(!navs.some(n=>n[0]===parts[0]))return;page=parts[0];routeParts=parts;const hash='#'+parts.join('/');if(location.hash!==hash)history.pushState(null,'',hash);document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);};
window.addEventListener('popstate',()=>navigate(location.hash.slice(1)));
const routeBeforeInit=location.hash.slice(1);
try{document.body.classList.toggle('compact',localStorage.getItem('veyago-compact')==='true');document.body.classList.toggle('no-motion',localStorage.getItem('veyago-motion')==='false');}catch{}
function redrawPreservingFocus(input){const name=input.dataset.query,start=input.selectionStart;render();const next=document.querySelector(`[data-query="${name}"]`);if(next){next.focus();if(next.setSelectionRange){try{next.setSelectionRange(start,start);}catch{}}}}
document.addEventListener('input',e=>{if(e.target.matches('[data-query]')){queries[e.target.dataset.query]=e.target.value;redrawPreservingFocus(e.target);}});
/* Showing images is a per-message decision the reader makes, not a setting
   they set once and forget. It resets on reload, deliberately. */
document.addEventListener('click', e => {
  const btn = e.target.closest?.('[data-show-images]');
  if (!btn) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  window.__mailShowImages = [...(window.__mailShowImages || []), btn.dataset.showImages];
  render();
}, true);

document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){const {view:key,value}=view.dataset;if(key==='ticketScope')ticketScope=value;if(key==='projectMode')projectMode=value;if(key==='crmMode')crmMode=value;if(key==='agendaMode')agendaMode=value;render();return;}const day=e.target.closest('[data-day]');if(day){selectedDay=Number(day.dataset.day);agendaMode='day';render();return;}const star=e.target.closest('[data-star]');if(star){mails[Number(star.dataset.star)].starred=!mails[Number(star.dataset.star)].starred;render();return;}if(e.target.closest('[data-print-invoice]'))window.print();});
document.addEventListener('change',e=>{const target=e.target;if(target.matches('[data-project-task]')){e.stopImmediatePropagation();const p=projects.find(p=>String(p.id)===target.dataset.projectTask),i=Number(target.dataset.task);p.checked??=[];p.checked=target.checked?[...new Set([...p.checked,i])]:p.checked.filter(n=>n!==i);activityRecord((target.checked?'Completed: ':'Reopened: ')+p.tasks[i]);render();toast(target.checked?'Task completed':'Task reopened');return;}if(target.matches('[data-record-kind]')){const {recordKind:kind,recordId,field}=target.dataset;const collection={tickets,projects,crm:contacts}[kind];const record=kind==='crm'?collection[Number(recordId)]:collection.find(r=>String(r.id)===String(recordId));if(record){record[field]=target.value;activityRecord('Updated '+(record.title||record.name));render();toast('Updated in this demo session');}return;}if(target.id==='compact-setting'||target.id==='motion-setting'){const compact=target.id==='compact-setting';document.body.classList.toggle(compact?'compact':'no-motion',compact?target.checked:!target.checked);try{localStorage.setItem(compact?'veyago-compact':'veyago-motion',String(target.checked));}catch{}toast('Preference updated');}},true);
document.addEventListener('submit',e=>{const form=e.target;if(form.matches('[data-note-form]')){e.preventDefault();const data=new FormData(form),body=String(data.get('note')).trim();if(!body)return;const kind=form.dataset.noteForm,id=form.dataset.recordId;recordNotes[kind][id]??=[];recordNotes[kind][id].push({body,time:'Just now'});render();toast('Note added');}if(form.matches('[data-ticket-reply]')){e.preventDefault();const data=new FormData(form),body=String(data.get('body')).trim();if(!body)return;const id=form.dataset.ticketReply;recordNotes.tickets[id]??=[];recordNotes.tickets[id].push({body,label:String(data.get('mode')),time:'Just now'});render();toast('Message added to this demo conversation');}if(form.matches('[data-add-task]')){e.preventDefault();const value=String(new FormData(form).get('task')).trim();if(!value)return;const p=projects.find(p=>String(p.id)===form.dataset.addTask);p.tasks.push(value);render();toast('Task added');}});

projectRows = function(){
/* Same empty state as the base version in app.js — this override replaces it
   wholesale, so it has to carry it too. */
if(!projects.length)return '<p class="quiet-text" style="padding:4px 19px 20px">No projects yet. Create one and it will show here with its progress.</p>';
return `<div class="project-list">${projects.slice(0,3).map(p=>`<a class="project-row" href="#projects/${p.id}"><div class="project-logo ${p.style}">${esc(p.initial)}</div><div><div class="project-name">${esc(p.name)}</div><div class="project-meta">${esc(p.client)}${p.due?` · Due ${esc(p.due)}`:''}</div></div><div><div class="progress-caption">${checkedTasks(p)} / ${p.tasks.length} tasks</div><div class="progress"><i style="width:${p.tasks.length?checkedTasks(p)/p.tasks.length*100:0}%"></i></div></div>${ownerAvatar(p)}</a>`).join('')}</div>`;};
/* the notifications bell is handled in app.js, from live data */

navigate(routeBeforeInit||'overview');
